1	// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
2	// and future backends). One C++20 binary that selects a model (fast / cycle
3	// / hybrid), resolves engines at runtime, and either passes through to a single
4	// engine or orchestrates a hybrid round-trip.
5	//
6	// This file owns argument dispatch only: parse the CLI, route to a command.
7	// Each subcommand below resolves to its handler as its feature lands (F1-F13);
8	// until then it stubs out, keeping the command surface stable.
9	#include <cstdio>
10	#include <cstdlib>
11	#include <exception>
12	#include <string>
13	#include <string_view>
14	
15	#include "cli.hpp"
16	#include "dev_mode.hpp"
17	#include "repo_root.hpp"
18	
19	namespace {
20	
21	using andes_sim::Cli;
22	using andes_sim::is_dev_mode;
23	
24	// Known command names. run/list/doctor get handlers as each feature lands; the
25	// rest are stable slots for unfinished ROADMAP features, kept here so `find`
26	// routes them to the "not yet implemented" stub rather than "unknown command",
27	// while never appearing in `--help` (print_usage renders only the
28	// run/list/doctor blocks, so the product never advertises half-built work).
29	// Developer build/test/state-diff tooling lives in scripts/, not the binary.
30	// Display strings (briefs, modes, options) live in the help model below.
31	struct Subcommand {
32	  std::string_view name;
33	};
34	
35	constexpr Subcommand kSubcommands[] = {
36	    {"run"},     {"list"},   {"doctor"},
37	    {"profile"}, {"cluster"}, {"estimate"},
38	};
39	
40	const Subcommand* find(std::string_view name) {
41	  for (const Subcommand& s : kSubcommands)
42	    if (s.name == name) return &s;
43	  return nullptr;
44	}
45	
46	// ---- help model: the user-facing surface rendered as a command tree --------
47	//
48	// `run`'s two subcommand groups -- the modes (the composition axis) ...
49	struct ModeRow {
50	  const char* name;
51	  const char* brief;
52	};
53	constexpr ModeRow kRunModes[] = {
54	    {"fast", "QEMU only -- functional, full speed"},
55	    {"cycle", "one cycle-accurate engine, from reset"},
56	    {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
57	};
58	
59	// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
60	// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
61	struct TargetRow {
62	  const char* name;
63	  const char* brief;
64	  bool dev;
65	};
66	constexpr TargetRow kListTargets[] = {
67	    {"models", "the modes and their engines", false},
68	    {"engines", "discovered cycle-accurate engines", false},
69	    {"fixtures", "internal test ELFs (developer target)", true},
70	};
71	
72	// ... and `run`'s options. Each `flag` carries its own leading indent (the pc
73	// boundaries nest under --trigger pc). `tag` marks a required option (and WHEN
74	// it is required); `dev` hides it unless ANDESIM_DEV is set.
75	struct OptRow {
76	  const char* flag;  // includes its own leading indent
77	  const char* tag;
78	  const char* brief;
79	  bool dev;
80	};
81	constexpr OptRow kRunOpts[] = {
82	    {"  --mode fast|cycle|hybrid", "REQUIRED", "which mode to run", false},
83	    {"  --trigger marker|pc", "REQUIRED for hybrid", "the ROI delimiter", false},
84	    {"    --pc-start <sym|0x>", "REQUIRED for --trigger pc", "ROI start boundary", false},
85	    {"    --pc-end <sym|0x>", "REQUIRED for --trigger pc", "ROI end boundary", false},
86	    {"  --engine <id>", "", "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)", false},
87	    {"  --mem-size <spec>", "", "guest RAM, e.g. 256M / 2G (hybrid: max 2G; fast: QEMU -m; cycle: ignored)", false},
88	    {"  --dry-run", "", "print the exact engine command(s) and exit, running nothing (fast/cycle/hybrid)", false},
89	    {"  --verify", "", "cross-check the hybrid run against a QEMU oracle", false},
90	    {"  --gdb", "", "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)", false},
91	    {"  --gdb-port <port>", "", "override the --gdb port (fast 1234, cycle 9104)", false},
92	    {"  -- <args...>", "", "forward everything after -- verbatim to the engine (fast/cycle only; hybrid rejects -- args)", false},
93	};
94	
95	// A major command line at column 0: `name   brief`.
96	void print_major(std::FILE* out, const char* name, const char* brief) {
97	  std::fprintf(out, "%-7s %s\n", name, brief);
98	}
99	
100	// A subcommand/target line, indented two under its command: `  name   brief`.
101	void print_sub(std::FILE* out, const char* name, const char* brief) {
102	  std::fprintf(out, "  %-9s %s\n", name, brief);
103	}
104	
105	// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
106	void print_opt(std::FILE* out, const OptRow& o) {
107	  if (o.tag[0])
108	    std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
109	  else
110	    std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
111	}
112	
113	// `run`: major line, the mode subcommands, then the option list (dev options
114	// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
115	void print_run_block(std::FILE* out) {
116	  print_major(out, "run", "run one simulation");
117	  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
118	  std::fputs("\n", out);
119	  for (const OptRow& o : kRunOpts) {
120	    if (o.dev && !is_dev_mode()) continue;
121	    print_opt(out, o);
122	  }
123	}
124	
125	void print_list_block(std::FILE* out) {
126	  print_major(out, "list", "list what is available");
127	  for (const TargetRow& t : kListTargets) {
128	    if (t.dev && !is_dev_mode()) continue;
129	    print_sub(out, t.name, t.brief);
130	  }
131	}
132	
133	void print_doctor_block(std::FILE* out) {
134	  print_major(out, "doctor", "check toolchain + fixtures are present");
135	}
136	
137	// Top-level `andesim --help`: the whole tree -- every major command, its
138	// subcommands, and run's full option list, so one screen shows everything.
139	void print_usage(std::FILE* out) {
140	  std::fputs("usage: andesim <command> [options] <ELF> [-- <engine args>]\n\n",
141	             out);
142	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
143	             out);
144	  print_run_block(out);
145	  std::fputs("\n", out);
146	  print_list_block(out);
147	  std::fputs("\n", out);
148	  print_doctor_block(out);
149	  std::fputs(
150	      "\n'andesim run --help' / 'andesim list --help' for per-command "
151	      "detail.\n",
152	      out);
153	}
154	
155	// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
156	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
157	  if (sc.name == "run") { print_run_block(out); return; }
158	  if (sc.name == "list") { print_list_block(out); return; }
159	  if (sc.name == "doctor") { print_doctor_block(out); return; }
160	  // A Hidden/unfinished command: a stable usage line, no advertised detail.
161	  std::fprintf(out, "usage: andesim %.*s [args...]\n",
162	               static_cast<int>(sc.name.size()), sc.name.data());
163	}
164	
165	}  // namespace
166	
167	int main(int argc, char** argv) {
168	  using namespace andes_sim;
169	
170	  Cli cli = parse_cli(argc, argv);
171	  if (!cli.error.empty()) {
172	    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
173	    return 2;
174	  }
175	
176	  if (cli.subcommand.empty()) {  // no command, or top-level -h
177	    if (cli.help) {
178	      print_usage(stdout);
179	      return 0;
180	    }
181	    print_usage(stderr);
182	    return 2;
183	  }
184	
185	  const Subcommand* sc = find(cli.subcommand);
186	  if (!sc) {
187	    std::fprintf(stderr, "andesim: unknown command '%s'\n\n",
188	                 cli.subcommand.c_str());
189	    print_usage(stderr);
190	    return 2;
191	  }
192	
193	  if (cli.help) {
194	    print_subcommand_help(*sc, stdout);
195	    return 0;
196	  }
197	
198	  // Every subcommand stubs out until its handler lands (run/list/doctor arrive
199	  // feature by feature). Resolve the repo root so the discovery path -- which
200	  // every handler relies on -- stays live and observable from the scaffold.
201	  std::string root;
202	  try {
203	    root = repo_root().string();
204	  } catch (const std::exception& e) {
205	    root = std::string("<unknown: ") + e.what() + ">";
206	  }
207	  std::fprintf(stderr, "andesim %s: not yet implemented (repo root: %s)\n",
208	               cli.subcommand.c_str(), root.c_str());
209	  return 3;
210	}
